"""Smooth the Persian wording of post 14343 (rank-1 article) without touching structure.
Headings, links, images, shortcodes, <style> blocks and the URL are left as they are; only sentences inside paragraphs and list items change.
Input : top-post-raw.html (live raw content)   Output: top-post-polished.html
"""
import re, sys
SRC = sys.argv[1] if len(sys.argv) > 1 else 'top-post-raw.html'
OUT = sys.argv[2] if len(sys.argv) > 2 else 'top-post-polished.html'
s = open(SRC, encoding='utf-8').read()
n_swaps = 0
MISSING = []

def swap(a, b, new):
    """replace the text from the unique marker `a` through the first `b` after it (both included)"""
    global s, n_swaps
    if s.count(a) != 1:
        MISSING.append(f'start marker found {s.count(a)}x: {a[:70]!r}'); return
    i = s.index(a)
    j = s.find(b, i)
    if j < 0:
        MISSING.append(f'end marker not found after: {a[:60]!r} -> {b[:60]!r}'); return
    j += len(b)
    s = s[:i] + new + s[j:]
    n_swaps += 1

