# ── safety checks: nothing structural may change ──
old = open(SRC, encoding='utf-8').read()
H = lambda t: re.findall(r'<h[1-6][^>]*>.*?</h[1-6]>', t, re.S)
assert H(old) == H(s), 'headings changed!'
A = lambda t: sorted(re.findall(r'<a [^>]*href="[^"]+"', t))
assert A(old) == A(s), 'links changed!'
I = lambda t: re.findall(r'<img [^>]*>', t)
assert I(old) == I(s), 'images changed!'
St = lambda t: re.findall(r'<style>.*?</style>', t, re.S)
assert St(old) == St(s), 'style blocks changed!'
print('headings, links, images and style blocks are identical to the live version')
txt = lambda t: re.sub(r'\s+', ' ', re.sub(r'<style>.*?</style>|<[^>]+>', ' ', t, flags=re.S))
print('visible text chars:', len(txt(old)), '->', len(txt(s)))
